import { uuidv7 } from "@nexus/core";
import { timestamp, uuid } from "drizzle-orm/pg-core";

/** Time-ordered primary key generated by the application (UUIDv7). */
export const id = () =>
  uuid()
    .primaryKey()
    .$defaultFn(() => uuidv7());

export const createdAt = () => timestamp({ withTimezone: true }).defaultNow().notNull();
export const updatedAt = () =>
  timestamp({ withTimezone: true })
    .defaultNow()
    .$onUpdate(() => new Date())
    .notNull();
